const style='<style>body{font:16px Arial;padding:20px}label,fieldset{display:block;margin:12px}input,select,textarea{padding:5px}[contenteditable]{border:1px solid;width:300px;min-height:30px}</style>';
export function phase5Fixture(id) {
 const head=`<!doctype html>${style}<h1>Employment application</h1>`;
 if(id==='workday-employer-b')return phase5Fixture('workday-employer-a').replace('<button id=trigger type=button role=combobox aria-labelledby=q aria-controls=menu>Select one</button>','<input id=trigger readonly role=combobox aria-labelledby=q aria-controls=menu placeholder="Select one">').replace("trigger.textContent='United States'","trigger.value='United States'").replace("trigger.textContent='Select one'","trigger.value=''");
 if(['workday-employer-a','workday-employer-b','ashby-search'].includes(id))return head+`<form><div class="select__control" data-automation-id="formField"><label id=q>Country</label><button id=trigger type=button role=combobox aria-labelledby=q aria-controls=menu>Select one</button><button id=clear type=button aria-label="Clear selection">Clear</button></div><div id=menu role=listbox hidden></div></form><script>trigger.onclick=()=>{menu.hidden=false;menu.innerHTML='<input role=textbox type=search aria-label="Search countries">';menu.querySelector('input').addEventListener('input',()=>setTimeout(()=>{const o=document.createElement('button');o.type='button';o.role='option';o.textContent='United States';o.onclick=()=>{trigger.dataset.selected='United States';trigger.textContent='United States';menu.hidden=true;menu.innerHTML='';};menu.append(o)},150));};clear.onclick=()=>{delete trigger.dataset.selected;trigger.textContent='Select one';};</script>`;
 if(id==='native')return head+`<form onsubmit="event.preventDefault();window.__submitted++"><label>First name<input id=text></label><label>Describe a project<textarea id=paragraph></textarea></label><label>Email address<input id=email type=email></label><label>Number of projects<input id=number type=number min=0></label><label>Start date<input id=date type=date></label><label>Skills<select id=multi multiple><option>Python</option><option>JavaScript</option><option>Java</option></select></label><label id=richlabel>Describe your experience</label><div id=rich contenteditable=true role=textbox aria-labelledby=richlabel></div><fieldset><legend>Preferred office</legend><label><input type=radio name=office value=Remote>Remote</label><label><input type=radio name=office value=London>London</label></fieldset><label>Current job<input type=checkbox id=check></label><fieldset><legend>Skills</legend><label><input type=checkbox name=skills value=Python>Python</label><label><input type=checkbox name=skills value=JavaScript>JavaScript</label><label><input type=checkbox name=skills value=Java>Java</label></fieldset><fieldset><legend>Graduation date</legend><label>Month<input id=month placeholder=MM type=number min=1 max=12></label><label>Day<input id=day placeholder=DD type=number min=1 max=31></label><label>Year<input id=year placeholder=YYYY type=number min=1900 max=2100></label></fieldset><button type=submit>Submit application</button></form><script>window.__submitted=0;</script>`;
 if(['revert','invalid','stale','edit','undo','cancel'].includes(id))return head+`<form><label id=question>First name<input id=first></label><label>Email address<input id=email type=email></label></form><script>first.addEventListener('change',()=>{${id==='revert'?"setTimeout(()=>first.value='',180);":id==='invalid'?"setTimeout(()=>{first.setCustomValidity('Rejected by fixture');first.setAttribute('aria-invalid','true')},150);":id==='stale'?"setTimeout(()=>question.firstChild.textContent='Last name',100);":''}});</script>`;
 if(['upload','upload-error','upload-pending'].includes(id))return head+`<form><div data-upload><label>Resume<input id=file type=file accept=application/pdf></label><span id=status></span></div></form><script>const statusNode=document.querySelector('#status');file.addEventListener('change',()=>setTimeout(()=>{${id==='upload-error'?"statusNode.setAttribute('role','alert');statusNode.textContent='Upload rejected';":id==='upload-pending'?"statusNode.setAttribute('aria-busy','true');statusNode.textContent='Uploading';":"statusNode.dataset.uploadState='complete';statusNode.textContent='Uploaded';"}},120));</script>`;
 if(id==='repeats')return head+`<form><section data-automation-id=workExperience><h2>Work experience</h2><div data-automation-id=workExperienceItem data-repeat-group=jobs><label>Employer<input name="experience[0].company"></label><label>Job title<input name="experience[0].title"></label><button type=button data-automation-id=deleteWorkExperience>Remove job</button></div><button type=button data-automation-id=addWorkExperience>Add work experience</button></section></form><script>const region=document.querySelector('section');region.addEventListener('click',e=>{if(e.target.dataset.automationId==='deleteWorkExperience')e.target.parentElement.remove();if(e.target.dataset.automationId==='addWorkExperience'){const block=region.querySelector('[data-repeat-group]').cloneNode(true),i=region.querySelectorAll('[data-repeat-group]').length;block.querySelectorAll('input').forEach(el=>{el.value='';el.name=el.name.replace('[0]','['+i+']')});region.insertBefore(block,e.target)}});</script>`;
 if(id==='unknown-repeat')return head+`<form><h2>Work experience</h2><label>Employer<input></label><button data-automation-id=addWorkExperience>Add work experience</button></form><script>window.__clicks=0;document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();__clicks++});</script>`;
 if(id==='nested')return head+`<iframe src="/phase5/inner"></iframe>`;
 if(id==='inner')return `<iframe src="/phase5/undo"></iframe>`;
 if(id==='steps-invalid')return head+`<form><div>Step 1 of 2</div><label>Email address<input id=email type=email value=invalid required></label><button type=button id=next>Next</button><button type=submit>Submit application</button></form><script>window.__clicks=0;window.__submitted=0;next.onclick=()=>__clicks++;document.querySelector('form').onsubmit=e=>{e.preventDefault();__submitted++};</script>`;
 throw Error('Unknown phase5 fixture '+id);
}
